pub(crate) fn internet_manifest() -> IndicatorManifest {
    IndicatorManifest { id: "internet", topic_id: "internet.status", order: 20, title: "Internet Status", icon_id: "plug", initial_state: "loading", admin_interactive: true, render_indicator: render_internet_indicator, render_modal: render_internet_modal, collector: Some(internet_collector) }
}

fn render_internet_indicator(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<button type="button" class="indicator loading internet-indicator" data-indicator="internet" data-modal-kind="internet" data-modal-title="Internet Status" data-internet-status-indicator aria-label="Checking Internet Status" title="Checking internet connection..."><svg class="indicator-icon indicator-icon-plug" data-packed-icon="plug" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 2h2v5h2V2h2v5h2V2h2v7a5 5 0 0 1-4 4.9V17h3v2h-3v3h-2v-3H8v-2h3v-3.1A5 5 0 0 1 7 9V2z"/></svg><svg class="indicator-icon indicator-icon-spinner" data-packed-icon="spinner" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 2a10 10 0 0 1 10 10h-3a7 7 0 0 0-7-7V2z"/></svg></button>"##.to_string() }
fn render_internet_modal(ctx: IndicatorRenderContext) -> String { let _ = ctx.session; r##"<div class="internet-status-modal" data-modal-kind-body="internet"><div class="status-section"><p class="status-text ${internetState.status}" data-modal-status data-route-read="/api/status">${internetStatusModalText()}</p></div>${indicatorAdminSection(`${internetAdminDetailsHtml()}<div class="speed-test-section"><div class="button-row"><button class="primary-button" data-speed-test-button data-modal-fetch="/api/status/internet/speedtest" data-method="POST" ${internetState.isSpeedTesting || internetState.status === 'loading' ? 'disabled' : ''}>${internetState.isSpeedTesting ? 'Running Speed Test...' : 'Run Speed Test'}</button></div>${internetSpeedTestHtml()}</div>`)}<pre class="readout action-output" data-modal-output></pre></div>"##.to_string() }
fn internet_collector(session: Session) -> Result<serde_json::Value, String> { collect_indicator_topic("internet.status", session) }
